def solve(facts):
    from collections import defaultdict
    states = {(0, -1, 0, 0): (1, 0)}
    for _ in range(facts['length']):
        nxt = defaultdict(lambda: (0, 0))
        for (r, prev, s, c), (ways, total) in states.items():
            for d in facts['alphabet']:
                if d == prev:
                    continue
                nc = c + (d == facts['target_digit'])
                if nc > facts['target_count']:
                    continue
                ns = s + d
                if ns > facts['sum_max']:
                    continue
                key = ((r * 10 + d) % facts['modulus'], d, ns, nc)
                w, t = nxt[key]
                nxt[key] = (w + ways, t + total + ways * d)
        states = nxt
    count = digit_sum_total = 0
    for (r, prev, s, c), (ways, total) in states.items():
        if r == facts['residue'] and facts['sum_min'] <= s <= facts['sum_max'] and c == facts['target_count']:
            count += ways
            digit_sum_total += total
    return {'count': count, 'digit_sum_total': digit_sum_total}

def check(answer, facts):
    from itertools import product
    count = 0
    total = 0
    for digits in product(facts['alphabet'], repeat=facts['length']):
        if any(digits[i] == digits[i-1] for i in range(1, len(digits))):
            continue
        s = sum(digits)
        if not (facts['sum_min'] <= s <= facts['sum_max']):
            continue
        if sum(d == facts['target_digit'] for d in digits) != facts['target_count']:
            continue
        r = 0
        for d in digits:
            r = (r * 10 + d) % facts['modulus']
        if r == facts['residue']:
            count += 1
            total += s
    return isinstance(answer, dict) and answer.get('count') == count and answer.get('digit_sum_total') == total
